local M = class("PetardTaskInfoControl",LikeOO.OOControlBase)

function M:onEnter()
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
    elseif msg == "btn_closeBtn" then
        self:closeView()
    elseif msg == "btn_canGotBtn" then
        self.m_model:getNetData("double_twelve_recv_score_reward", data, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                RewardUtil:rewardTipsByData(response.reward)
                self.m_model:setScoreDataById(data.score_id)
                self.m_view:refreshUI()
                EventDispatcher:dipatchEvent("forceRefresh_petardInfoData")
            end
        end, nil, nil, nil)
    end
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView("PetardActivity.PetardTask")
        self:closeView("PetardActivity.PetardMain")
        self:closeView()
        return true
    end
    return false
end

function M:destroy()
    M.super.destroy(self)
end

return M